solution.solution.cpp:
#include <utility>
#include <vector>

struct Camera { double x, y, zoom; double screenW, screenH; };
struct Box { double x, y, w, h; };

std::pair<double, double> toScreen(const Camera& c, double worldX, double worldY)
{
    return { (worldX - c.x) * c.zoom + c.screenW / 2, (worldY - c.y) * c.zoom + c.screenH / 2 };
}

bool visible(const Camera& c, const Box& b)
{
    // The world rectangle the camera shows: half the screen, divided by the zoom, either side of its position.
    const double halfW{ c.screenW / 2 / c.zoom }, halfH{ c.screenH / 2 / c.zoom };
    const double left{ c.x - halfW }, right{ c.x + halfW }, top{ c.y - halfH }, bottom{ c.y + halfH };
    return b.x < right && b.x + b.w > left && b.y < bottom && b.y + b.h > top;
}

std::vector<int> cull(const Camera& c, const std::vector<Box>& boxes)
{
    std::vector<int> shown;
    for (int i{ 0 }; i < static_cast<int>(boxes.size()); ++i)
        if (visible(c, boxes[static_cast<std::size_t>(i)])) shown.push_back(i);
    return shown;
}

unitTests:
const Camera cam{ 100, 50, 2, 800, 600 };
TEST("centre maps to the centre") { const auto [sx, sy] = toScreen(cam, 100, 50); CHECK_NEAR(sx, 400, 1e-9); CHECK_NEAR(sy, 300, 1e-9); }
TEST("zoom scales distances") { const auto [sx, sy] = toScreen(cam, 110, 40); CHECK_NEAR(sx, 420, 1e-9); CHECK_NEAR(sy, 280, 1e-9); }
TEST("the corners of the view") { const auto [sx, sy] = toScreen(cam, -100, -100); CHECK_NEAR(sx, 0, 1e-9); CHECK_NEAR(sy, 0, 1e-9); }
TEST("inside and outside") { CHECK(visible(cam, { 90, 40, 20, 20 })); CHECK(!visible(cam, { 500, 50, 10, 10 })); CHECK(!visible(cam, { 100, -300, 10, 10 })); }
TEST("partly visible counts") { CHECK(visible(cam, { 290, 40, 50, 10 })); }
TEST("touching the edge does not count") { CHECK(!visible(cam, { 300, 40, 10, 10 })); CHECK(!visible(cam, { -110, 40, 10, 10 })); }
TEST("a box bigger than the view") { CHECK(visible(cam, { -1000, -1000, 3000, 3000 })); }
TEST("cull keeps order") { CHECK(cull(cam, { { 90, 40, 5, 5 }, { 9000, 0, 1, 1 }, { 0, 0, 1, 1 } }) == std::vector<int>({ 0, 2 })); }

